const b = $input.first().json.body || {};
const mime = b.mimeType || 'image/jpeg';
const img = b.imageBase64 || '';
const hint = String(b.hint || '').slice(0, 200);
const sys = 'Kamu membantu toko tenis Tirtonic Tennis Store (Yogyakarta) mencatat barang baru dari foto. Baca teks di produk, kotak, tag, atau label dengan teliti. Keluarkan HANYA JSON object {"name":string,"color":string,"category":string,"gender":string}. name = merek + seri/model persis seperti tertulis, mis. "Adidas Adizero Ubersonic 4" atau "Luxilon Alu Power 125 Rough Reel 220m"; jangan menebak merek/seri yang tidak terlihat, isi "" bila tidak terbaca. color = warna utama dalam Bahasa Indonesia huruf kecil, maks 3 warna dipisah "/", mis. "putih/hitam"; "" bila tidak jelas. category = salah satu: sepatu, raket, tas, baju, celana, aksesoris, lainnya (senar, grip, overgrip, bola, kaus kaki, topi, wristband = aksesoris). gender = men, women, unisex, atau "" (hanya untuk sepatu/baju/celana, dari label Men/Women/M/W/Wmns atau bentuk produk; "" bila tidak yakin atau kategori lain). Jangan menambah teks lain.';
const ask = 'Isi data barang dari foto ini.' + (hint ? ' Nama dari nota (bisa salah ketik, perbaiki bila foto lebih jelas): ' + hint : '');
return [{ json: { body: {
  model: 'gpt-4o',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sys },
    { role: 'user', content: [
      { type: 'text', text: ask },
      { type: 'image_url', image_url: { url: `data:${mime};base64,${img}` } }
    ] }
  ]
} } }];

const c = $input.first().json;
const txt = (c.choices && c.choices[0] && c.choices[0].message && c.choices[0].message.content) || '{}';
let o; try { o = JSON.parse(txt); } catch (e) { o = {}; }
return [{ json: { name: o.name || '', color: o.color || '', category: o.category || '', gender: o.gender || '' } }];
